#include "ImageDisk.h"
#include "Constants.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
#include <algorithm>
namespace RetroMediaLab::MediaEngine::ImageDisk {
namespace {
using namespace Constants;
void available(MediaFileSystems::Bytes bytes,std::size_t offset,std::size_t count,Section section){if(offset>bytes.size()||count>bytes.size()-offset)throw MediaError(DiagnosticCode::ImdTruncated,{std::string(Sections[std::size_t(section)]),std::to_string(offset),std::to_string(count),std::to_string(offset>bytes.size()?0:bytes.size()-offset)});}
std::vector<std::uint8_t> byteMap(MediaFileSystems::Bytes bytes,std::size_t& offset,std::size_t count,Section section){available(bytes,offset,count,section);std::vector<std::uint8_t> result(bytes.begin()+std::ptrdiff_t(offset),bytes.begin()+std::ptrdiff_t(offset+count));offset+=count;return result;}
}
Image readDetailed(MediaFileSystems::Bytes bytes,std::stop_token token){using namespace Constants;const auto end=std::find(bytes.begin(),bytes.end(),Terminator);const auto commentEnd=end==bytes.end()?-1:std::int64_t(end-bytes.begin());if(commentEnd<std::int64_t(SignatureSize)||!std::equal(Signature.begin(),Signature.end(),bytes.begin()))throw MediaError(DiagnosticCode::ImdSignature,{std::to_string(commentEnd),std::to_string(bytes.size())});Image image;for(auto value:bytes.first(std::size_t(commentEnd)))image.comment.push_back(char(value<=AsciiMaximum?value:AsciiReplacement));std::size_t offset=std::size_t(commentEnd)+1;
 while(offset<bytes.size()){checkCancellation(token);available(bytes,offset,TrackHeader,Section::TrackHeader);const auto mode=bytes[offset+ModeOffset],cylinder=bytes[offset+CylinderOffset],flags=bytes[offset+HeadFlagsOffset],count=bytes[offset+CountOffset],code=bytes[offset+SizeOffset];offset+=TrackHeader;if(mode>MaxMode||!count)throw MediaError(DiagnosticCode::ImdTrackHeader,{std::to_string(mode),std::to_string(count)});Track track;track.mode=Mode(mode);track.cylinder=cylinder;track.head=flags&HeadMask;const auto numbers=byteMap(bytes,offset,count,Section::SectorNumberMap);const auto cylinders=flags&CylinderMap?byteMap(bytes,offset,count,Section::CylinderMap):std::vector<std::uint8_t>{};const auto heads=flags&HeadMap?byteMap(bytes,offset,count,Section::HeadMap):std::vector<std::uint8_t>{};std::vector<std::int32_t> sizes(count);
  if(code!=ExplicitSize){if(code>MaxSizeCode)throw MediaError(DiagnosticCode::ImdSizeCode,{std::to_string(code)});std::fill(sizes.begin(),sizes.end(),std::int32_t(BaseSize<<code));}else{available(bytes,offset,std::size_t(count)*SizeMapEntry,Section::SectorSizeMap);for(std::size_t i=0;i<count;++i)sizes[i]=bytes[offset+i*SizeMapEntry]|(std::uint16_t(bytes[offset+i*SizeMapEntry+1])<<BitsPerByte);offset+=std::size_t(count)*SizeMapEntry;}
  for(std::size_t i=0;i<count;++i){available(bytes,offset,1,Section::SectorRecord);const auto type=bytes[offset++];if(type>MaxRecord)throw MediaError(DiagnosticCode::ImdRecordType,{std::to_string(type)});Sector sector;sector.cylinder=cylinders.empty()?cylinder:cylinders[i];sector.head=heads.empty()?track.head:heads[i];sector.number=numbers[i];sector.size=sizes[i];sector.recordType=RecordType(type);if(!hasData(sector.recordType))sector.data.resize(std::size_t(sector.size));else if(compressed(sector.recordType)){available(bytes,offset,1,Section::CompressedValue);sector.data.resize(std::size_t(sector.size),bytes[offset++]);}else sector.data=byteMap(bytes,offset,std::size_t(sector.size),Section::SectorData);track.sectors.push_back(std::move(sector));}image.tracks.push_back(std::move(track));}
 image.sectorImage=buildImage(image.tracks);return image;
}
std::shared_ptr<const MediaFileSystems::SectorImage> read(MediaFileSystems::Bytes bytes,std::stop_token token){return readDetailed(bytes,token).sectorImage;}
}
